solution_code:
#include <iostream>

class Box {
public:
    int width;
    int height;
    int depth;

    int volume() const {
        return width * height * depth;
    }

    int surfaceArea() const {
        return 2 * (width * height + height * depth + width * depth);
    }
};

void report(const Box& b) {
    std::cout << "Volume: " << b.volume()
              << ", Surface: " << b.surfaceArea() << "\n";
}

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int w, h, d;
        std::cin >> w >> h >> d;
        Box b;
        b.width = w;
        b.height = h;
        b.depth = d;
        report(b);
    }
    return 0;
}
